          '<code>sales.orders</code> (n7): the description and the tag <code>pii</code> are still as undo left them, so both are <b class="m">put back</b> to empty. The owner ben was never undo\'s, so it is not touched.',
          '<code>sales.orders.email</code> (n8): undo filled nothing here, so there is nothing to take back.',
          'The arrow <code>reports.daily → n7</code> was added by undo and is <b>removed</b>. The arrows from <code>sales</code> to n7 and from n7 to n8 were there before undo and stay.',
          'Inherited tags are recomputed: <code>pii</code> leaves n7, and with it email and currency.',
          'The graph is now exactly what it was just before undo. The dump is the same, byte for byte.'],
    table:tbl('What redo did with each row',['row of d1','what undo had done','still as undo left it?','redo'],[
      ['sales.orders.total (n4)','restored it','yes','<b>removed</b>'],
      ['sales.orders (n2 into n7)<br>description','filled it','yes','<b class="m">put back</b> to empty'],
      ['','tags: filled <code>pii</code>','yes','<b class="m">put back</b> to empty'],
      ['','owner: left ben alone','not undo\'s','unchanged'],
      ['sales.orders.email (n3 into n8)','filled nothing','','unchanged'],
      ['arrow n7 → total','added it','goes with total','<b>removed</b>'],
      ['arrow daily → n7','added it','yes','<b>removed</b>'],
      ['arrow daily → total','added it','goes with total','<b>removed</b>'],
      ['arrows sales → n7, n7 → n8','found them already there','not undo\'s','unchanged']]),
    nodes:function(){return redone(null,'fields put back · n2 in journal',{desc:1})},edges:beforeUndoEdges},
   {tab:'Undo again',title:'undo d1, a second time',
    text:['The rows redo took back have no outcome, so undo decides each one afresh.',
          'Nothing changed in between, so it decides the same way: n2 is merged into n7 and fills the same two fields, and total is restored with its three arrows.',
          'The graph is again exactly what the first undo produced. Undo and redo can go back and forth.'],table:'',
    nodes:function(){return usual[3].nodes},edges:afterUndoEdges}
  ];

  var TAX='Order total with tax';
  var edited=[
   {tab:'After undo',title:'Where undo d1 left the graph',
    text:['A simpler case: after delete d1 nothing else happened, and undo d1 restored all three nodes and all five arrows.'],table:'',
    nodes:function(){return [S(),R(),D(),O(RS),M(RS),T(RS)]},edges:function(){return ed(all('res'))}},
   {tab:'Edit',title:'A person edits a restored node',
    text:['A person rewrites the description of <code>sales.orders.total</code>. This happens after the undo.'],table:'',
    nodes:function(){return [S(),R(),D(),O(),M(),T({desc:TAX,chg:{desc:1}})]},edges:function(){return ed()}},
   {tab:'Redo',title:'redo d1',
    text:['Children first. <code>sales.orders.email</code>: untouched and nothing attached, so it is <b>removed</b> again.',
          '<code>sales.orders.total</code>: a person wrote on it after the undo. Removing it would lose that edit, so it is <b class="r">kept</b>, reason <code>written_since_undo</code>.',
          '<code>sales.orders</code>: nobody wrote on it, but it still has a child, so it is <b class="r">kept</b>, reason <code>still_in_use</code>.',
          'The arrows of the two kept nodes stay, reason <code>end_kept</code>. A node that stays is not left half connected.',
          'The report says the delete was only partly redone, and why. To remove the rest, the person deletes it with a new delete.'],
    table:tbl('What redo did with each row',['row of d1','redo','reason'],[
      ['sales.orders.email (n3)','<b>removed</b>',''],
      ['sales.orders.total (n4)','<b class="r">kept</b>','written_since_undo'],
      ['sales.orders (n2)','<b class="r">kept</b>','still_in_use'],
      ['arrow orders → email','<b>removed</b>','goes with email'],
      ['the other four arrows','<b class="r">kept</b>','end_kept']]),
    nodes:function(){return [S(),R(),D(),O({state:'restored',note:'kept · still in use'}),M(OUT1),
                             T({desc:TAX,state:'restored',note:'kept · written since undo'})]},
    edges:function(){return ed({'sales>orders':'res','orders>email':'ghost','orders>total':'res','daily>orders':'res','daily>total':'res'})}}
  ];

  var NEWDESC='Orders, one row each';
  function afterUndoWith(desc,chg){
    return [n('sales','n1',null,'Sales schema',['finance','gdpr'],[]),
            n('refunds','n5',null,'Approved refunds only',[],['finance','gdpr']),
            n('daily','n6',null,'Daily revenue',[],[]),
            n('orders','n7','ben',desc,['pii'],['finance','gdpr'],{newId:1,chg:chg}),
            n('email','n8',null,'Hashed customer email',['hashed'],['pii','finance','gdpr'],{newId:1,ownerSet:1}),
            n('total','n4','asha','Order total, EUR',[],['pii','finance','gdpr']),
            n('currency','n9',null,null,[],['pii','finance','gdpr'],{newId:1})];
  }
  var liveAfterUndo=[e('sales','refunds','c'),e('sales','orders','c'),e('orders','email','c'),e('orders','currency','c'),
                     e('orders','total','c'),e('daily','orders','r'),e('daily','total','r')];
  var rewritten=[
   {tab:'After undo',title:'Where undo d1 left the graph',
    text:['The end of the usual undo story again. Undo filled two fields on <code>n7</code>: the description "One row per order" and the tag <code>pii</code>.'],table:'',
    nodes:function(){return usual[3].nodes},edges:afterUndoEdges},
   {tab:'Edit',title:'A person rewrites a field undo filled',
    text:['A person changes the description of <code>sales.orders</code> (n7) to "Orders, one row each". That is a write by a person after the undo.'],table:'',
    nodes:function(){return afterUndoWith(NEWDESC,{desc:1})},edges:liveAfterUndo},
   {tab:'Redo',title:'redo d1',
    text:['Redo goes through the fields undo filled on n7, one at a time.',
          'Description: a person has written it since the undo, so it <b class="r">stays</b> as they wrote it, reason <code>written_since_undo</code>.',
          'Tags: still as undo left them, so <code>pii</code> is <b class="m">put back</b> to empty. It also leaves email and currency.',
          '<code>sales.orders.total</code> is untouched, so it is <b>removed</b> again with its arrows.',
          'Each field is decided on its own, as in undo. One edited field does not stop the others from going back.'],
    table:tbl('Field by field on n7',['field','what undo had done','since the undo','redo'],[
      ['description','filled "One row per order"','a person rewrote it','<b class="r">kept</b> as the person wrote it'],
      ['tags','filled <code>pii</code>','untouched','<b class="m">put back</b> to empty'],
      ['owner','left ben alone','untouched','unchanged']]),
    nodes:function(){return redone(NEWDESC,'tags put back · description kept',{})},edges:beforeUndoEdges}
  ];

  var twoUndos=[
   {tab:'Both undone',title:'Two deletes, both undone',
    text:['From the undo story "A neighbour is deleted later". d1 deleted <code>sales.orders</code>, then d2 deleted <code>reports.daily</code>.',
          'Undo d1 ran first. It restored the three nodes, but the two arrows from <code>reports.daily</code> had to wait on d2.',
          'Undo d2 ran second. It restored <code>reports.daily</code> and then retried the two waiting arrows. So those two arrows are rows of d1 that the undo of d2 decided.'],table:'',
    nodes:function(){return [S(),R(),O({note:'restored by undo d1'}),M(),T(),D({state:'restored',note:'restored by undo d2'})]},
    edges:function(){return ed({'daily>orders':'res','daily>total':'res'})}},
   {tab:'Redo d2',title:'redo d2, the newest undo first',
    text:['Redo takes back every row the undo of d2 decided: <code>reports.daily</code>, and the two arrows it retried.',
          '<code>reports.daily</code> is untouched and both arrows on it are coming out with it, so it is <b>removed</b> again.',
          'The two arrows are rows of d1, so they do not go into the journal of d2. They go back to what they were before: <b class="s">skipped</b>, <code>waiting_on: d2</code>.',
          'The graph is exactly what it was before undo d2. Undoing d2 again later would retry the arrows again.'],table:'',
    nodes:function(){return [S(),R(),O(),M(),T(),D({state:'ghost',note:'out again, in journal d2'})]},
    edges:function(){return ed({'daily>orders':'skp','daily>total':'skp'})}},
   {tab:'Or: redo d1',title:'What if d1 is redone first instead',
    text:['Start again from "Both undone" and run redo d1 while the undo of d2 still stands.',
          '<code>sales.orders.email</code> has nothing else attached and is <b>removed</b>.',
          '<code>sales.orders.total</code> carries an arrow from <code>reports.daily</code>. The undo of d2 put that arrow there, so redo d1 is not taking it back. Total is <b class="r">kept</b>, reason <code>still_in_use</code>.',
          '<code>sales.orders</code> is kept for the same reason, and because it still has a child.',
          'Redo the newest undo first and nothing is kept this way.'],table:'',
    nodes:function(){return [S(),R(),D(),O({state:'restored',note:'kept · still in use'}),M(OUT1),T({state:'restored',note:'kept · still in use'})]},
    edges:function(){return ed({'sales>orders':'res','orders>email':'ghost','orders>total':'res'})}}
  ];

  var redoFlows=[
    {name:'Redo straight after undo',why:'Nothing changed since the undo, so redo takes all of it back.',stages:straight},
    {name:'A person edited a restored node',why:'A node a person wrote on after the undo stays, and so does its parent.',stages:edited},
    {name:'A person rewrote a filled field',why:'A field undo filled goes back to what it was, unless a person has written it since.',stages:rewritten},
    {name:'Two undos, then redo',why:'Redo takes back the rows its undo decided, including rows of an earlier delete.',stages:twoUndos}
  ];

  function buttons(list,sel,label){
    return list.map(function(it,i){return '<button role="tab" data-i="'+i+'" aria-selected="'+(i===sel?'true':'false')+'">'+label(it,i)+'</button>'}).join('');
  }
  function pick(ev){var b=ev.target.closest('button');return b?+b.dataset.i:-1}
  /* One stepper: p is the prefix of its element ids ('' for undo, 'r' for redo). */
  function mount(flows,p){
    var svg=document.getElementById(p+'story'),txt=document.getElementById(p+'storytext'),ft=document.getElementById(p+'fieldtable'),
        flowtabs=document.getElementById(p+'flowtabs'),stagetabs=document.getElementById(p+'stagetabs'),why=document.getElementById(p+'flowwhy');
    var cur={f:0,s:0};
    function render(){
      var fl=flows[cur.f],s=fl.stages[cur.s];
      flowtabs.innerHTML=buttons(flows,cur.f,function(it){return it.name});
      stagetabs.innerHTML=buttons(fl.stages,cur.s,function(it,i){return (i+1)+' · '+it.tab});
      why.textContent=fl.why;
      svg.innerHTML=val(s.edges).map(drawEdge).join('')+val(s.nodes).map(drawNode).join('');
      svg.setAttribute('aria-label',fl.name+', step '+(cur.s+1)+': '+s.title);
      txt.innerHTML='<h4>'+s.title+'</h4><ul>'+s.text.map(function(t){return '<li>'+t+'</li>'}).join('')+'</ul>';
      ft.innerHTML=s.table||'';
    }
    flowtabs.addEventListener('click',function(ev){var i=pick(ev);if(i<0)return;cur.f=i;cur.s=0;render()});
    stagetabs.addEventListener('click',function(ev){var i=pick(ev);if(i<0)return;cur.s=i;render()});
    render();
  }
  mount(flows,'');
  mount(redoFlows,'r');
})();
</script>

