/* ---- building blocks shared by the extra stories ---- */
function mk(s,id,owner,desc,own,inh){
  return function(o){var d=n(s,id,owner,desc,own.slice(),inh.slice(),{});if(o){for(var k in o)d[k]=o[k]}return d};
}
var S=mk('sales','n1',null,'Sales schema',['finance'],[]),
    O=mk('orders','n2','asha','One row per order',['pii'],['finance']),
    R=mk('refunds','n5',null,'One row per refund',[],['finance']),
    M=mk('email','n3','dana','Customer email',['contact'],['pii','finance']),
    T=mk('total','n4','asha','Order total, EUR',[],['pii','finance']),
    D=mk('daily','n6',null,'Daily revenue',[],[]),
    A=mk('archive','n10',null,'Retired data',['old'],[]);
var BASE=[['sales','orders','c'],['sales','refunds','c'],['orders','email','c'],['orders','total','c'],['daily','orders','r'],['daily','total','r']];
function ed(over,extra){
  var out=[];
  BASE.forEach(function(b){var k=b[0]+'>'+b[1],st=(over&&(k in over))?over[k]:'live';if(st)out.push(e(b[0],b[1],b[2],st))});
  return out.concat(extra||[]);
}
function all(st,more){var o={};BASE.forEach(function(b){if(b[0]+'>'+b[1]!=='sales>refunds')o[b[0]+'>'+b[1]]=st});if(more){for(var k in more)o[k]=more[k]}return o}
var J1={state:'ghost',note:'in journal d1'},J2={state:'ghost',note:'in journal d2'},
    RS={state:'restored',note:'restored'},SK={state:'skipped',note:'skipped, waits on d2'};
var startStage={tab:'Start',title:'Start: six nodes',text:['The same six nodes as in the usual case.'],table:'',
  nodes:function(){return [S(),O(),R(),M(),T(),D()]},edges:function(){return ed()}};

  edges:function(){return ed({'daily>orders':'res','daily>total':'res'})}}
];

/* ---- story 3: the parent is deleted later (nodes wait) ---- */
var parentGone=[startStage,d1Stage,
 {tab:'Delete d2',title:'Person B deletes the sales subtree (d2)',
  text:['<code>sales</code> and <code>sales.refunds</code> move into the journal of d2, with the arrow between them.',
        '<code>sales.orders</code> is not in d2. It was already gone.'],
  table:'',
  nodes:function(){return [D(),S(J2),R(J2),O(J1),M(J1),T(J1)]},edges:function(){return ed(all('ghost',{'sales>refunds':'ghost'}))}},
 {tab:'Undo d1',title:'Person A runs undo d1 while d2 still stands',
  text:['<code>sales.orders</code>: its name is free, but its parent <code>sales</code> is not live. It is <b class="s">skipped</b>, reason <code>parent_not_live</code>, <code>waiting_on: d2</code>.',
        'Its two columns: their parent was just skipped, so they are skipped the same way.',
        'All five arrows are skipped, because at least one end of each is not live.',
        'The graph does not change. The report says why, and which delete has to be undone first.'],
  table:'',
  nodes:function(){return [D(),S(J2),R(J2),O(SK),M(SK),T(SK)]},edges:function(){return ed(all('skp',{'sales>refunds':'ghost'}))}},
 {tab:'Undo d2',title:'Person B runs undo d2',
  text:['<code>sales</code> and <code>sales.refunds</code> are <b class="r">restored</b>.',
        'Undo then retries the rows of d1 that wait on d2, parents first. <code>sales.orders</code> now has a live parent and is restored. Its columns follow, then all five arrows.',
        'Inherited tags are recomputed as each node comes back.'],
  table:'',
  nodes:function(){return [D(),S(RS),R(RS),O(RS),M(RS),T(RS)]},edges:function(){return ed(all('res',{'sales>refunds':'res'}))}}
];

/* ---- story 4: the recreated node is deleted again (most recent wins, type) ---- */
var X={'orders>email':0,'daily>orders':0,'daily>total':0};
