            elif human and op["kind"] == "add_edge": human_edge[(op["from_id"], op["to_id"], op["type"])] = (t, "add")
            elif human and op["kind"] == "repoint_edge":
                human_edge[(op["from_id"], op["to_id"], op["type"])] = (t, "remove")
                new = (op.get("new_from_id", op["from_id"]), op.get("new_to_id", op["to_id"]), op["type"])
                human_edge[new] = (t, "add")
    except Exception:
        if not failures: failures.append(f"seq {seq_no} step {t}: {traceback.format_exc(limit=3).strip().splitlines()[-1]} | trail: {' ; '.join(log[-12:])}")
    finally:
        await store.close()
    return failures

async def main():
    n, steps = int(sys.argv[2]), int(sys.argv[3]); db = Path("fuzz.db"); bad = []; cmds = 0
    for i in range(n):
        log = []
        f = await one(i, db, steps, log); cmds += len(log)
        bad += f[:1]
    kinds = {}
    for b in bad:
        k = b.split(": ", 1)[1].split(" | ")[0]
        k = " ".join(w for w in k.split() if not (w[:1] in "do" and w[1:].isdigit()))[:90]
        kinds.setdefault(k, []).append(b)
    print(f"{n} sequences, {cmds} commands, {len(bad)} sequences with a failure, {len(kinds)} kinds")
    for k, items in sorted(kinds.items(), key=lambda x: -len(x[1])):
        print(f"\n[{len(items)}x] {k}\n   e.g. {items[0][:900]}")
asyncio.run(main())
