ROOT = Path(sys.argv[1]); sys.path.insert(0, str(ROOT))
from graph_undo.applier import Applier
from graph_undo.dumper import dump
from graph_undo.loader import load
from graph_undo.redo import redo
from graph_undo.rounds import CommandError
from graph_undo.store import Store
from graph_undo.undo import undo

SEED = ROOT / "fixture_small" / "seed.jsonl"
EXTRA = ["sales.orders.currency", "archive", "archive.old", "reports", "reports.weekly", "sales.orders.email.hash"]
FIELDS = ("description", "owner", "tags")

def parse(text):
    nodes, edges = {}, set()
    for line in text.splitlines():
        r = json.loads(line)
        if "qualified_name" in r: nodes[r["id"]] = r
        else: edges.add((r["from_id"], r["to_id"], r["type"]))
    return nodes, edges

def whole(nodes, edges):
    probs = []
    names = [n["qualified_name"] for n in nodes.values()]
    if len(names) != len(set(names)): probs.append("duplicate name")
    parent = {}
    for f, t, k in edges:
        if f not in nodes or t not in nodes: probs.append(f"dangling {f}>{t}")
        if k == "contains":
            if t in parent: probs.append(f"two parents {t}")
            parent[t] = f
