        tags, cur, seen = set(), nid, set()
        while cur is not None and cur in nodes:
            if cur in seen: probs.append("loop"); break
            seen.add(cur); tags |= set(nodes[cur]["tags"]); cur = parent.get(cur)
        if sorted(tags) != n["effective_tags"]: probs.append(f"tags of {n['qualified_name']}")
    return probs

async def one(seq_no, db, steps, log):
