    db.unlink(missing_ok=True)
    await load(str(db), str(SEED))
    store = await Store.open(str(db)); app = Applier(store)
    names = [json.loads(l)["qualified_name"] for l in SEED.read_text().splitlines() if '"node"' in l] + EXTRA
    failures = []; t = 0; n_op = 0
    deletes, delete_step, undo_step, redo_step = [], {}, {}, {}
    human_write, human_edge, human_gone = {}, {}, {}
    def fail(msg): failures.append(f"seq {seq_no} step {t}: {msg} | trail: {' ; '.join(log[-12:])}")
