        try:
            await (undo if cmd == "undo" else redo)(store, op)
        except CommandError as e:
            log.append(f"{cmd} {op} -> refused"); return None
        except Exception as e:
            log.append(f"{cmd} {op} -> CRASH"); fail(f"{cmd} {op} raised {type(e).__name__}: {e}"); raise
        log.append(f"{cmd} {op} ({store.writes - w}w)")
