    async def journal_ok(op, nodes):
        live_names = {n["qualified_name"] for n in nodes.values()}
        rows = await store.fetchall("SELECT id, qualified_name, parent_id, outcome, merged_into FROM removed_nodes WHERE delete_op = ?", (op,))
        by = {r[0]: r for r in rows}
        for nid, name, parent, outcome, into in rows:
            if outcome is None: fail(f"undo {op}: node row {name} has no outcome")
            if outcome == "restored" and nid not in nodes: fail(f"undo {op}: {name} restored but not live")
            if outcome == "merged" and into not in nodes: fail(f"undo {op}: {name} merged into a node that is not live")
            if outcome == "skipped":
                p_live = parent is None or parent in nodes or (parent in by and by[parent][3] in ("restored", "merged"))
                if name not in live_names and p_live: fail(f"undo {op}: INVARIANT 2: {name} skipped, name free, parent live")
        if await store.fetchval("SELECT 1 FROM removed_edges WHERE delete_op = ? AND outcome IS NULL", (op,)): fail(f"undo {op}: arrow row without outcome")
    try:
