                    continue
                since = delete_step[op]
                if not set(nodes) <= set(a_nodes) or not edges <= a_edges: fail(f"undo {op} removed something")
                for (nid, f), s in human_write.items():
                    if s > since and nid in nodes and (nid not in a_nodes or a_nodes[nid][f] != nodes[nid][f]): fail(f"undo {op}: INVARIANT 1: human value {f} changed")
