                    if s > since and what == "remove" and e not in edges and e in a_edges: fail(f"undo {op}: INVARIANT 1: arrow a person moved away is back {e}")
                for nid, s in human_gone.items():
                    if s > max(since, redo_step.get(op, 0)) and nid not in nodes and nid in a_nodes: fail(f"undo {op}: INVARIANT 1: node a person deleted is back")
                for p in whole(a_nodes, a_edges): fail(f"after undo {op}: {p}")
