                    r_text = await snap()
                    if r_text != text: fail(f"redo {op} straight after undo != dump before the undo")
                    if await run("redo", op) != 0 or await snap() != r_text: fail(f"second redo {op} not idempotent")
                    redo_step[op] = t
                    if rng.random() < 0.5:
