            if kind == "redo":
                op = rng.choice(deletes); w = await run("redo", op)
                if w is None: continue
                a_text = await snap(); a_nodes, a_edges = parse(a_text)
                if w == 0:
                    if a_text != text: fail(f"repeat redo {op} changed the dump")
                    continue
                if not set(a_nodes) <= set(nodes) or not a_edges <= edges: fail(f"redo {op} added something")
