                for (nid, f), s in human_write.items():
                    if s > since and nid in nodes and (nid not in a_nodes or a_nodes[nid][f] != nodes[nid][f]): fail(f"redo {op}: human value {f} written after the undo lost")
                for e, (s, what) in human_edge.items():
                    if s > since and what == "add" and e in edges and e not in a_edges: fail(f"redo {op}: arrow a person added after the undo is gone {e}")
                for p in whole(a_nodes, a_edges): fail(f"after redo {op}: {p}")
                if await store.fetchval("SELECT 1 FROM removed_nodes WHERE delete_op = ?1 AND outcome = 'skipped' AND waiting_on IS NOT NULL", (op,)): fail(f"redo {op} left a row waiting")
                redo_step[op] = t
