                continue
            n_op += 1; op_id = f"o{n_op}"
            if kind == "delete" and live:
                root = rng.choice(live); op_id = f"d{len(deletes) + 1}"
                op = {"op_id": op_id, "actor": rng.choice(["human", "human", "ingest"]), "kind": "delete_subtree", "root_id": root}
            elif kind == "ingest":
                name = rng.choice(names)
                op = {"op_id": op_id, "actor": "ingest", "kind": "ingest_node", "qualified_name": name, "type": rng.choice(["table", "view", "column"]), "parent": name.rsplit(".", 1)[0] if "." in name else None}
            elif kind == "edit" and live:
