            elif kind == "add" and len(live) > 1:
                a, b = rng.sample(live, 2)
                op = {"op_id": op_id, "actor": rng.choice(["human", "ingest"]), "kind": "add_edge", "from_id": a, "to_id": b, "type": rng.choice(["references", "references", "contains"])}
            elif kind == "repoint" and [e for e in edges if e[2] == "references"] and live:
                f, to, k = rng.choice(sorted(e for e in edges if e[2] == "references"))
                op = {"op_id": op_id, "actor": rng.choice(["human", "human", "ingest"]), "kind": "repoint_edge", "from_id": f, "to_id": to, "type": k, "new_to_id": rng.choice(live)}
            elif kind == "move" and [e for e in edges if e[2] == "contains"]:
                f, to, k = rng.choice(sorted(e for e in edges if e[2] == "contains"))
                op = {"op_id": op_id, "actor": "human", "kind": "repoint_edge", "from_id": f, "to_id": to, "type": k, "new_from_id": rng.choice(live)}
            else:
                continue
            status, reason = await app.apply_one(op)
            log.append(f"{op['kind']}:{op_id}{'' if status == 'applied' else '(rej)'}")
            a_nodes, a_edges = parse(await snap())
            for p in whole(a_nodes, a_edges): fail(f"after {op['kind']}: {p}")
