rows = [json.loads(l) for l in open(src)]
by = {r["uuid"]: r for r in rows if r.get("uuid")}

SYSTEM_PREFIXES = ("The user hasn't heard from you", "[SYSTEM NOTIFICATION", "<task-notification>",
                   "Your response above was stopped", "Caveat:", "<system-reminder>")

def clean(text: str) -> str:
    return re.sub(r"<system-reminder>.*?</system-reminder>", "", text, flags=re.S).strip()

def user_blocks(r):
    c = r["message"]["content"]
    texts = [c] if isinstance(c, str) else [b.get("text", "") for b in c if b.get("type") == "text"]
    texts = [clean(t) for t in texts]
    return [t for t in texts if t and not t.startswith(SYSTEM_PREFIXES)]

last = max((r for r in rows if r.get("type") == "user" and r.get("message") and marker in json.dumps(r["message"])),
           key=lambda r: r["timestamp"])
chain, r = [], last
while r is not None:
    chain.append(r)
    r = by.get(r.get("parentUuid"))
chain.reverse()

kept = []
for r in chain:
    if r.get("isSidechain") or r.get("type") not in ("user", "assistant") or r.get("isMeta"):
        continue
    base = {k: r[k] for k in ("type", "uuid", "parentUuid", "timestamp", "sessionId") if k in r}
    if r["type"] == "user":
        if r.get("toolUseResult") is not None:
            continue
        texts = user_blocks(r)
        if not texts:
            continue
        kept.append({**base, "message": {"role": "user", "content": [{"type": "text", "text": t} for t in texts]}})
    else:
        m = r["message"]
        blocks = []
        for b in m.get("content", []):
            if b.get("type") == "text" and b.get("text", "").strip():
                blocks.append({"type": "text", "text": b["text"]})
            elif b.get("type") == "tool_use" and b.get("name") == "mcp__ccd_turn__wrap_up":
                shown = {k: b["input"][k] for k in ("recap", "ask", "actions") if k in b.get("input", {})}
                blocks.append({"type": "next_step_box", **shown})
        if blocks:
            kept.append({**base, "message": {"role": "assistant", "model": m.get("model"), "content": blocks}})

with open(out, "w") as fh:
    for rec in kept:
        fh.write(json.dumps(rec, ensure_ascii=False) + "\n")
print(f"{len(chain)} entries in the conversation chain, {len(kept)} messages written to {out}")
